/**
* Fetches a SPIDAR `/api/ai/*` endpoint across web preview, Chrome Extension popup/options,
* and content scripts injected into external webpages (with automatic fallback across
* live Cloud Run URLs and the extension background service worker to bypass strict page CSP).
*/
async function fetchBackendOrBridge(path, options = {}) {
	const cleanPath = path.startsWith("/") ? path : `/${path}`;
	const timeoutMs = options.timeoutMs || 18e3;
	if (typeof window !== "undefined" && !isChromeExtensionRuntime()) return fetch(cleanPath, {
		...options,
		signal: options.signal || AbortSignal.timeout(timeoutMs)
	});
	let lastError = null;
	for (const baseUrl of SPIDAR_CLOUD_BACKEND_FALLBACK_URLS) try {
		const res = await fetch(`${baseUrl}${cleanPath}`, {
			...options,
			signal: AbortSignal.timeout(timeoutMs)
		});
		if (res.ok || res.status === 400 || res.status === 401 || res.status === 429) return res;
	} catch (err) {
		lastError = err;
	}
	if (typeof chrome !== "undefined" && chrome?.runtime?.id && chrome?.runtime?.sendMessage) try {
		const bgRes = await new Promise((resolve) => {
			chrome.runtime.sendMessage({
				type: "SPIDAR_PROXY_FETCH",
				path: cleanPath,
				method: options.method || "POST",
				body: typeof options.body === "string" ? JSON.parse(options.body) : options.body
			}, (response) => {
				if (chrome.runtime.lastError) resolve(null);
				else resolve(response);
			});
		});
		if (bgRes && bgRes.ok && bgRes.data) return new Response(JSON.stringify(bgRes.data), {
			status: 200,
			headers: { "Content-Type": "application/json" }
		});
	} catch {}
	if (lastError) throw lastError;
	throw new Error(`Unable to reach SPIDAR Cloud Bridge (${cleanPath})`);
}
