/**
* Performs real web search and URL extraction via `/api/ai/search` (Google Search Grounding +
* DuckDuckGo + Crossref Academic + Live URL extraction), with direct Crossref fallback.
*/
async function searchWebSources(query, apiConfig) {
	const cleanQuery = String(query || "").trim();
	if (!cleanQuery) return {
		query: "",
		citations: [],
		groundedSummary: ""
	};
	try {
		const res = await fetchBackendOrBridge("/api/ai/search", {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				query: cleanQuery,
				apiConfig
			}),
			timeoutMs: 14e3
		});
		if (res.ok) {
			const data = await res.json();
			const list = Array.isArray(data?.citations) ? data.citations : Array.isArray(data?.sources) ? data.sources : null;
			if (list) return {
				query: data.query || cleanQuery,
				citations: list,
				groundedSummary: String(data.groundedSummary || "")
			};
		}
	} catch {}
	const citations = [];
	try {
		const crRes = await fetch(`https://api.crossref.org/works?query=${encodeURIComponent(cleanQuery)}&rows=4&select=title,URL,abstract,Author,published`, { signal: AbortSignal.timeout(6500) });
		if (crRes.ok) {
			const items = (await crRes.json())?.message?.items || [];
			for (const item of items) {
				const title = Array.isArray(item.title) ? item.title[0] : item.title;
				const url = item.URL;
				const rawAbstract = String(item.abstract || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
				const year = item.published?.["date-parts"]?.[0]?.[0] || "";
				if (title && url) citations.push({
					title: year ? `${title} (${year})` : String(title),
					url: String(url),
					snippet: rawAbstract.slice(0, 260) || `Peer-reviewed scholarly work indexed via Crossref (${url}).`,
					sourceType: "academic"
				});
			}
		}
	} catch {}
	return {
		query: cleanQuery,
		citations,
		groundedSummary: ""
	};
}
