	const defaultBase = provider === "openrouter" ? "https://openrouter.ai/api/v1" : provider === "qwen-local" ? "http://localhost:11434/v1" : "https://api.openai.com/v1";
	const base = (config.baseUrl || defaultBase).trim().replace(/\/+$/, "");
